// Зони влучання нових звірів — у системах кісток (розраховано з положень у моделі в спокої).
function beastHitZones(kind) {
  const asset = beastAsset(kind);
  const rig = BEAST_RIGS[kind];
  if (!asset || !rig) return null;
  return rig.zones.map((z) => {
    const b = asset.restWorld[asset.boneIndex[z.bone]];
    return { bone: z.bone, p: [z.at[0] - b.x, z.at[1] - b.y, z.at[2] - b.z], r: z.r, zone: z.zone };
  });
}

// Ікла самця кабана: нижні вигнуті догори й назад, верхні коротші, загнуті вгору (колір слонової кістки).
function buildTuskGeometry(base) {
  const pos = [];
  const nrm = [];
  const col = [];
  const idx = [];
  const sides = 7;
  const tube = (pts, r0, s) => {
    const n = pts.length;
    const start = pos.length / 3;
    const curve = new THREE.CatmullRomCurve3(pts);
    const P = curve.getSpacedPoints(10);
    let normal = new THREE.Vector3(1, 0, 0);
    const t = new THREE.Vector3();
    const b = new THREE.Vector3();
    for (let i = 0; i < P.length; i++) {
      const p = P[i];
      if (i < P.length - 1) t.subVectors(P[i + 1], p); else t.subVectors(p, P[i - 1]);
      t.normalize();
      normal.sub(b.copy(t).multiplyScalar(normal.dot(t))).normalize();
      if (normal.lengthSq() < 1e-6) normal.set(0, 0, 1);
      b.crossVectors(t, normal).normalize();
      const k = i / (P.length - 1);
      const r = r0 * (1 - 0.88 * k);
      const shade = 0.78 + 0.22 * k;
      for (let j = 0; j < sides; j++) {
        const a = (j / sides) * Math.PI * 2;
        const nx = normal.x * Math.cos(a) + b.x * Math.sin(a);
        const ny = normal.y * Math.cos(a) + b.y * Math.sin(a);
        const nz = normal.z * Math.cos(a) + b.z * Math.sin(a);
        pos.push((p.x + nx * r) * s, p.y + ny * r, p.z + nz * r);
        nrm.push(nx * s, ny, nz);
        col.push(Math.round(222 * shade), Math.round(210 * shade), Math.round(186 * shade), 120);
      }
    }
    for (let i = 0; i < P.length - 1; i++) {
      for (let j = 0; j < sides; j++) {
        const a = start + i * sides + j;
        const bb = start + i * sides + ((j + 1) % sides);
        if (s > 0) idx.push(a, a + sides, bb, bb, a + sides, bb + sides);
        else idx.push(a, bb, a + sides, bb, bb + sides, a + sides);
      }
    }
    return n;
  };
  const V = (x, y, z) => new THREE.Vector3(x, y, z);
  const [bx, by, bz] = base;
  for (const s of [-1, 1]) {
    tube([V(bx - 0.006, by - 0.012, bz - 0.01), V(bx + 0.006, by + 0.012, bz + 0.004), V(bx + 0.016, by + 0.04, bz - 0.006), V(bx + 0.019, by + 0.06, bz - 0.03)], 0.0085, s);
    tube([V(bx - 0.008, by + 0.03, bz - 0.03), V(bx + 0.004, by + 0.036, bz - 0.024), V(bx + 0.012, by + 0.05, bz - 0.036)], 0.006, s);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('normal', new THREE.Float32BufferAttribute(nrm, 3));
  g.setAttribute('color', new THREE.BufferAttribute(new Uint8Array(col), 4, true));
  g.setIndex(idx);
  g.computeBoundingSphere();
  return g;
}

/**
 * Модель звіра. Інтерфейс для поведінки той самий, що в оленя: object, update(dt, pose), setLod, setShadow,
 * boneMatrix. Поле pose.act задає особливу дію: 'sit', 'lie', 'sniff', 'root', 'eat', 'howl', 'pounce',
 * 'up' (стовпчиком), 'crouch' (лежка зайця), 'listen' (лисиця прислухається); pose.actT — час дії.
 */
class BeastModel {
  constructor(spec, kind, opts = {}) {
    beastInitTemps();
    const asset = beastAsset(kind);
    this.spec = spec;
    this.kind = kind;
    this.asset = asset;
    this.rig = BEAST_RIGS[kind];
    this.terrain = opts.terrain || null;
    const hdr = asset.header;
    this.object = new THREE.Group();
    this.object.name = `animal-${kind}`;
    const n = hdr.bones.length;
    this.bones = [];
    this.byName = {};
    for (let i = 0; i < n; i++) {
      const b = new THREE.Bone();
      b.name = hdr.bones[i].name;
      b.position.copy(asset.restLocal[i]);
      this.bones.push(b);
      this.byName[b.name] = b;
    }
    for (let i = 0; i < n; i++) {
      const p = asset.parent[i];
      if (p >= 0) this.bones[p].add(this.bones[i]);
      else this.object.add(this.bones[i]);
    }
    this.object.updateMatrixWorld(true);
    this.skeleton = new THREE.Skeleton(this.bones);
    const mat = beastMaterial(kind);
    this.meshes = asset.geometries.map((g) => {
      const m = new THREE.SkinnedMesh(g, mat);
      m.frustumCulled = false;
      m.castShadow = true;
      m.receiveShadow = true;
      this.object.add(m);
      return m;
    });
    this.object.updateMatrixWorld(true);
    for (const m of this.meshes) m.bind(this.skeleton, m.matrixWorld);
    this.lod = 0;
    this.meshes[1].visible = false;
    this.extras = [];
    this.lq = Array.from({ length: n }, () => new THREE.Quaternion());
    this.oq = Array.from({ length: n }, () => new THREE.Quaternion());
    this.op = Array.from({ length: n }, () => new THREE.Vector3());
    this.rootPos = asset.restWorld[0].clone();
    this.I = asset.boneIndex;
    const ff = hdr.footFwd || [0.05, 0.05];
    this.legs = DEER_LEGS.map((L) => this.legSetup(L, L.front ? ff[0] : ff[1]));
    this.restPitch = hdr.headPitch;
    const R = asset.restWorld;
    const neck1 = R[this.I.neck1];
    const head = R[this.I.head];
    this.neckRest = Math.atan2(head.z - neck1.z, head.y - neck1.y);
    this.neckLen = neck1.distanceTo(R[this.I.neck2]) + R[this.I.neck2].distanceTo(head);
    this.noseLocal = new THREE.Vector3(...hdr.nose).sub(head);
    // Середина кульшових суглобів відносно кореня (для поз «сидіти» і «стовпчиком»).
    this.hipRest = R[this.I.femBL].clone().add(R[this.I.femBR]).multiplyScalar(0.5);
    const n0 = spec.neck;
    const h0 = spec.head;
    this.s = {
      neck: n0.idle, headPitch: h0.idle, yaw: 0, tail: 0, alert: 0, pitch: 0, dead: 0, moving: 0,
      sit: 0, lie: 0, ground: 0, howl: 0, up: 0, crouch: 0, pounce: 0, listen: 0, eat: 0, jaw: 0, earsBack: 0, roll: 0, pant: 0,
    };
    this.gw = [1, 0, 0];
    this.earTimer = 2;
    this.twitch = 0;
    this.twitchSide = 0;
    this.tailTimer = 3;
    this.flick = 0;
    this.chew = Math.random() * 10;
    this.fallSide = Math.random() < 0.5 ? 1 : -1;
    this.skipFrames = 0;
    this.time = Math.random() * 100;
    this.pounceT = 0;
  }

  legSetup(L, footFwd) {
    const I = this.I;
    const R = this.asset.restWorld;
    const c = L.chain.map((nm) => I[nm]);
    const pas = c[c.length - 1];
    const foot = R[pas].clone().add(BEAST_V[0].set(0, -R[pas].y, footFwd));
    if (L.front) {
      const [scap, hum, rad, can] = c;
      return {
        front: true, scap, hum, rad, can, pas, foot, side: R[hum].x < 0 ? -1 : 1,
        l1: R[hum].distanceTo(R[rad]), l2: R[rad].distanceTo(R[can]),
        dirCan: R[pas].clone().sub(R[can]), dirPas: foot.clone().sub(R[pas]),
        rest: { hum: R[rad].clone().sub(R[hum]).normalize(), rad: R[can].clone().sub(R[rad]).normalize(), can: R[pas].clone().sub(R[can]).normalize(), pas: foot.clone().sub(R[pas]).normalize() },
        target: new THREE.Vector3(), ground: 0,
      };
    }
    const [fem, tib, met] = c;
    return {
      front: false, fem, tib, met, pas, foot, side: R[fem].x < 0 ? -1 : 1,
      l1: R[fem].distanceTo(R[tib]), l2: R[tib].distanceTo(R[met]),
      dirMet: R[pas].clone().sub(R[met]), dirPas: foot.clone().sub(R[pas]),
      rest: { fem: R[tib].clone().sub(R[fem]).normalize(), tib: R[met].clone().sub(R[tib]).normalize(), met: R[pas].clone().sub(R[met]).normalize(), pas: foot.clone().sub(R[pas]).normalize() },
      target: new THREE.Vector3(), ground: 0,
    };
  }

  setShadow(on) {
    for (const m of this.meshes) m.castShadow = on;
    for (const e of this.extras) e.castShadow = on;
  }

  setLod(level) {
    if (level === this.lod) return;
    this.lod = level;
    this.meshes[0].visible = level === 0;
    this.meshes[1].visible = level === 1;
  }

  // Ікла кабана-самця.
  setTusks(on) {
    for (const e of this.extras) {
      e.parent.remove(e);
      e.geometry.dispose();
    }
    this.extras = [];
    const t = this.asset.header.tusk;
    if (!on || !t || this.I.jaw === undefined) return;
    const jaw = this.byName.jaw;
    const jr = this.asset.restWorld[this.I.jaw];
    const g = buildTuskGeometry(t);
    const mesh = new THREE.Mesh(g, beastMaterial(this.kind));
    mesh.position.set(-jr.x, -jr.y, -jr.z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    mesh.frustumCulled = false;
    jaw.add(mesh);
    this.extras.push(mesh);
  }

  // Кістки за іменами; «body» і «neck» — назви зі старих моделей (для сумісності зі сторонніми перевірками).
  boneMatrix(name) {
    const b = this.byName[name] || this.byName[BEAST_BONE_ALIAS[name]];
    return b ? b.matrixWorld : null;
  }

  boneObject(name) {
    return this.byName[name] || this.byName[BEAST_BONE_ALIAS[name]] || null;
  }

  fk(i) {
    const p = this.asset.parent[i];
    if (p < 0) {
      this.oq[i].copy(this.lq[i]);
      this.op[i].copy(this.rootPos);
    } else {
      this.oq[i].multiplyQuaternions(this.oq[p], this.lq[i]);
      this.op[i].copy(this.asset.restLocal[i]).applyQuaternion(this.oq[p]).add(this.op[p]);
    }
  }

  aim(i, restDir, dir) {
    const p = this.asset.parent[i];
    const q = BEAST_Q[0].setFromUnitVectors(restDir, BEAST_V[15].copy(dir).normalize());
    this.oq[i].copy(q);
    this.lq[i].copy(BEAST_Q[1].copy(this.oq[p]).invert()).multiply(q);
    this.op[i].copy(this.asset.restLocal[i]).applyQuaternion(this.oq[p]).add(this.op[p]);
  }

  solve2(A, B, a, b, bendSign, out) {
    const d = BEAST_V[1].subVectors(B, A);
    let len = d.length();
    const maxL = (a + b) * 0.999;
    const minL = Math.abs(a - b) * 1.01 + 1e-4;
    if (len > maxL) {
      d.multiplyScalar(maxL / len);
      len = maxL;
    } else if (len < minL) {
      d.multiplyScalar(minL / Math.max(len, 1e-6));
      len = minL;
    }
    const u = BEAST_V[9].copy(d).divideScalar(len);
    const cosA = clamp((a * a + len * len - b * b) / (2 * a * len), -1, 1);
    const sinA = Math.sqrt(1 - cosA * cosA);
    const w = BEAST_V[2].set(0, -u.z, u.y).multiplyScalar(bendSign);
    w.sub(BEAST_V[3].copy(u).multiplyScalar(w.dot(u))).normalize();
    out.copy(A).addScaledVector(u, a * cosA).addScaledVector(w, a * sinA);
    return out;
  }

  update(dt, pose) {
    const s = this.s;
    const act = pose.act || '';
    const still = 1 - smoothstep(0.15, 0.6, pose.speed);
    s.neck = damp(s.neck, pose.neck, 3.2, dt);
    s.headPitch = damp(s.headPitch, pose.headPitch, 3.6, dt);
    s.yaw = damp(s.yaw, pose.lookYaw, 4, dt);
    s.tail = damp(s.tail, pose.tail, 5, dt);
    s.alert = damp(s.alert, pose.alert, 4, dt);
    s.pitch = damp(s.pitch, pose.bodyPitch, 6, dt);
    s.dead = pose.dead > s.dead ? Math.min(pose.dead, s.dead + dt * 1.3) : pose.dead;
    const v = pose.speed;
    s.moving = damp(s.moving, smoothstep(0.04, 0.3, v) * (1 - s.dead), 6, dt);
    const tgt = (name, rate) => {
      s[name] = damp(s[name], act === name ? 1 : 0, rate, dt);
    };
    // Пози, у яких звір стоїть на місці, гаснуть, щойно він рушає.
    s.sit = damp(s.sit, (act === 'sit' || act === 'howl') ? still : 0, 2.6, dt);
    s.lie = damp(s.lie, act === 'lie' ? still : 0, 1.6, dt);
    s.up = damp(s.up, act === 'up' ? still : 0, 4.5, dt);
    s.crouch = damp(s.crouch, act === 'crouch' ? 1 : 0, 3.5, dt);
    tgt('howl', 2.2);
    tgt('listen', 3);
    tgt('eat', 2.5);
    s.ground = damp(s.ground, (act === 'sniff' || act === 'root' || act === 'eat' || act === 'graze') ? 1 : 0, 3, dt);
    s.pant = damp(s.pant, pose.pant || 0, 1.5, dt);
    if (act === 'pounce') this.pounceT = pose.actT || 0;
    s.pounce = damp(s.pounce, act === 'pounce' ? 1 : 0, 10, dt);
    s.earsBack = damp(s.earsBack, pose.earsBack || 0, 6, dt);
    const gw = this.gw;
    const sp = this.rig.speeds;
    gw[0] = 1 - smoothstep(sp[0], sp[1], v);
    gw[2] = smoothstep(sp[2], sp[3], v);
    gw[1] = Math.max(0, 1 - gw[0] - gw[2]);
    this.earTimer -= dt;
    this.tailTimer -= dt;
    if (this.earTimer <= 0) {
      this.earTimer = 1.5 + Math.random() * 4;
      this.twitchSide = Math.random() < 0.5 ? 0 : 1;
      this.twitch = 1;
    }
    this.twitch = Math.max(0, this.twitch - dt * 4);
    if (this.tailTimer <= 0) {
      this.tailTimer = 2 + Math.random() * 5;
      this.flick = 1;
    }
    this.flick = Math.max(0, this.flick - dt * 2.5);
    this.chew += dt;
    this.time += dt;
    if (!this.object.visible) return;
    if (this.lod === 1 && this.skipFrames++ % 2 === 1) return;
    this.pose(pose);
  }

  // Положення кореня, за якого кульшові суглоби опиняються на висоті hipY (тулуб повернуто на pitch).
  rootForHip(pitch, pelvisRot, hipY, hipDz, out) {
    const A = this.asset;
    const I = this.I;
    const q = BEAST_Q[2].setFromAxisAngle(BEAST_AX, pitch);
    const qp = BEAST_Q[3].setFromAxisAngle(BEAST_AX, pelvisRot);
    // Кульшовий суглоб: корінь → таз → стегно (у системі моделі, якщо корінь у нулі).
    const pel = BEAST_V[12].copy(A.restLocal[I.pelvis]).applyQuaternion(q);
    const hipL = BEAST_V[13].copy(this.hipRest).sub(A.restWorld[I.pelvis]).applyQuaternion(qp).applyQuaternion(q);
    const hip = pel.add(hipL);
    out.set(0, hipY - hip.y, this.hipRest.z + hipDz - hip.z);
    return out;
  }

  pose(pose) {
    const s = this.s;
    const I = this.I;
    const A = this.asset;
    const R = A.restWorld;
    const rig = this.rig;
    const TAU = Math.PI * 2;
    const ph = pose.phase;
    const gw = this.gw;
    const moving = s.moving;
    const dead = s.dead;
    const fall = dead * dead * (3 - 2 * dead);
    const strides = rig.strides;
    const legLen = rig.leg;
    const lq = this.lq;
    for (const q of lq) q.identity();
    const alive = 1 - fall;
    // ── Пози, що змінюють положення тулуба ──
    const sit = s.sit * alive;
    const lie = s.lie * alive;
    const up = (rig.up ? s.up : 0) * alive;
    const crouch = s.crouch * alive;
    let pArc = 0;
    let pPitch = 0;
    if (s.pounce > 0.01) {
      // Стрибок лисиці: присід, політ дугою (тулуб від «носом угору» до «носом униз»), приземлення на передні лапи.
      const t = this.pounceT;
      const crouchW = smoothstep(0.0, 0.25, t) * (1 - smoothstep(0.32, 0.4, t));
      const fly = clamp((t - 0.38) / 0.5, 0, 1);
      const land = smoothstep(0.85, 0.95, t) * (1 - smoothstep(1.2, 1.6, t));
      pArc = (Math.sin(Math.PI * fly) * 1.5 - crouchW * 0.15) * legLen * s.pounce;
      pPitch = (crouchW * 0.12 + (fly > 0 && fly < 1 ? lerp(-0.55, 0.85, fly) : 0) + land * 0.45) * s.pounce;
      this.pounceFly = fly > 0 && fly < 1 ? s.pounce : 0;
      this.pounceLand = land * s.pounce;
    } else {
      this.pounceFly = 0;
      this.pounceLand = 0;
    }
    // ── Корінь: підскок, розгойдування, нахил, пози ──
    let bob = 0;
    let rock = 0;
    let flex = 0;
    for (let g = 0; g < 3; g++) {
      if (gw[g] <= 0) continue;
      const G = rig.gaits[g];
      bob += gw[g] * (g === 2 ? G.bob * Math.sin(TAU * ph + 0.6) : G.bob * Math.cos(TAU * ph * 2));
      if (g === 2) rock += gw[g] * 0.06 * Math.sin(TAU * ph + 1.4);
      flex += gw[g] * G.flex * Math.sin(TAU * (ph + G.flexPh));
    }
    bob *= moving;
    rock *= moving;
    flex *= moving;
    // Нюхати слід чи гризти: звір трохи присідає на передні лапи й тягнеться мордою донизу.
    const gr = s.ground * alive * (1 - s.lie);
    let pitch = (s.pitch + rock) * alive + pPitch + gr * rig.reachPitch;
    const rp = this.rootPos.copy(R[I.root]);
    rp.y += bob + pArc - gr * legLen * rig.reachDrop;
    let chestRot = -flex;
    let pelvisRot = flex * 0.8;
    if (sit > 0.001) {
      const S = rig.sit;
      const target = this.rootForHip(S.pitch, S.pelvis, S.hipY, S.hindDz * 0.3, BEAST_V[14]);
      rp.lerp(target, sit);
      pitch = lerp(pitch, S.pitch, sit);
      chestRot = lerp(chestRot, S.chest, sit);
      pelvisRot = lerp(pelvisRot, S.pelvis, sit);
    }
    if (up > 0.001) {
      const U = rig.up;
      const target = this.rootForHip(U.pitch, -0.35, U.hipY, 0.02, BEAST_V[14]);
      rp.lerp(target, up);
      pitch = lerp(pitch, U.pitch, up);
      chestRot = lerp(chestRot, 0.25, up);
      pelvisRot = lerp(pelvisRot, -0.35, up);
    }
    if (lie > 0.001 || crouch > 0.001) {
      const L = rig.lie;
      const w = Math.max(lie, crouch);
      rp.y = lerp(rp.y, L.y + (crouch > lie ? -0.006 : 0), w);
      pitch = lerp(pitch, L.pitch + s.pitch * 0.6, w);
      chestRot = lerp(chestRot, 0, w);
      pelvisRot = lerp(pelvisRot, 0.05, w);
    }
    rp.y = lerp(rp.y, rig.sideY, fall);
    BEAST_E.set(pitch * alive, 0, fall * 1.42 * this.fallSide, 'YXZ');
    lq[I.root].setFromEuler(BEAST_E);
    lq[I.chest].setFromAxisAngle(BEAST_AX, chestRot * alive);
    lq[I.pelvis].setFromAxisAngle(BEAST_AX, pelvisRot * alive);
    this.fk(I.root);
    this.fk(I.pelvis);
    this.fk(I.chest);
    // ── Ноги ──
    const scale = this.object.scale.x || 1;
    const terrain = this.terrain;
    const useTerrain = terrain && this.lod === 0 && fall < 0.5 && s.pounce < 0.5;
    const ox = this.object.position.x;
    const oz = this.object.position.z;
    const oy = this.object.position.y;
    const yaw = this.object.rotation.y;
    const cy = Math.cos(yaw);
    const sy = Math.sin(yaw);
    const fly = this.pounceFly;
    for (let li = 0; li < 4; li++) {
      const leg = this.legs[li];
      const foot = leg.foot;
      let dz = 0;
      let lift = 0;
      let flexA = 0;
      let flexF = 0;
      for (let g = 0; g < 3; g++) {
        if (gw[g] <= 0) continue;
        const G = rig.gaits[g];
        const sweep = Math.min(G.duty * strides[g], 1.15 * legLen);
        const p = fract(ph + G.off[li]);
        let z;
        let l = 0;
        let fa = 0;
        let ff = 0;
        if (p < G.duty) {
          z = sweep * (0.5 - p / G.duty);
        } else {
          const t = (p - G.duty) / (1 - G.duty);
          const e = t * t * (3 - 2 * t);
          z = sweep * (-0.5 + e);
          l = Math.sin(Math.PI * t) * (leg.front ? G.liftF : G.liftB);
          fa = Math.pow(Math.sin(Math.PI * Math.min(1, t * 1.15)), 1.3) * (leg.front ? G.carpus : G.hock);
          ff = Math.sin(Math.PI * t) * G.fetlock;
        }
        dz += gw[g] * z;
        lift += gw[g] * l;
        flexA += gw[g] * fa;
        flexF += gw[g] * ff;
      }
      dz *= moving;
      lift *= moving;
      flexA *= moving;
      flexF *= moving;
      // Розподіл на «кінцеві» кути: зап'ясток (передні) і поворот плесна (задні).
      let distal = leg.front ? flexA : -flexA * 0.6;
      let tx = foot.x;
      let tz = foot.z + dz;
      let lay = 0;
      if (sit > 0.001) {
        const S = rig.sit;
        tz += (leg.front ? S.frontDz : S.hindDz) * sit;
        if (!leg.front) distal = lerp(distal, S.met, sit);
      }
      if (up > 0.001 && !leg.front) {
        tz += 0.02 * up;
        distal = lerp(distal, -1.5, up);
      }
      const lw = Math.max(lie, crouch);
      if (lw > 0.001) {
        const L = rig.lie;
        tx = lerp(tx, foot.x * (leg.front ? 1.05 : L.splay), lw);
        tz += (leg.front ? (crouch > lie ? 0.25 : 1) * L.frontDz : L.hindDz) * lw;
        distal = lerp(distal, leg.front ? (crouch > lie ? 0.2 : -1.5) : -1.5, lw);
        lay = lw;
      }
      const T = leg.target.set(tx, 0, tz);
      let ground = 0;
      if (useTerrain) {
        const wx = ox + (T.x * cy + T.z * sy) * scale;
        const wz = oz + (-T.x * sy + T.z * cy) * scale;
        ground = clamp((terrain.heightAt(wx, wz) - oy) / scale, -0.35 * legLen / 0.6, 0.35 * legLen / 0.6);
      }
      leg.ground = damp(leg.ground, ground, 18, 1 / 60);
      T.y = leg.ground + lift + lay * 0.004;
      if (leg.front) {
        lq[leg.scap].setFromAxisAngle(BEAST_AX, -dz * 0.5 / Math.max(legLen, 0.1) * 0.6);
        this.fk(leg.scap);
        this.fk(leg.hum);
      }
      // Лапи в польоті (стрибок лисиці) — відносно тулуба; у «стовпчику» зайця передні лапи звисають перед грудьми.
      if (fly > 0.001 || (up > 0.001 && leg.front)) {
        const w = leg.front ? Math.max(fly, up) : fly;
        const local = BEAST_V[11];
        if (up > fly && leg.front) {
          local.copy(this.op[leg.hum]).add(BEAST_V[10].set(0, -0.62 * legLen, 0.22 * legLen));
        } else {
          const off = BEAST_V[10];
          if (leg.front) off.set(0, 0.12 * legLen, 0.38 * legLen);
          else off.set(0, 0.1 * legLen, -0.42 * legLen);
          local.set(foot.x, foot.y, foot.z).sub(R[I.root]).add(off).applyQuaternion(this.oq[I.root]).add(this.rootPos);
        }
        T.lerp(local, w);
        if (leg.front) distal = lerp(distal, up > fly ? 1.4 : 0.3, w);
        else distal = lerp(distal, -0.2, w);
        flexF = lerp(flexF, leg.front ? 0.6 : 0.2, w);
      }
      const F = BEAST_V[4].copy(leg.dirPas).applyAxisAngle(BEAST_AX, flexF * 0.9).negate().add(T);
      if (leg.front) {
        const S = this.op[leg.hum];
        const C = BEAST_V[5].copy(leg.dirCan).applyAxisAngle(BEAST_AX, distal).negate().add(F);
        const E = this.solve2(S, C, leg.l1, leg.l2, 1, BEAST_V[6]);
        this.aim(leg.hum, leg.rest.hum, BEAST_V[7].subVectors(E, S));
        this.aim(leg.rad, leg.rest.rad, BEAST_V[7].subVectors(C, E));
        this.aim(leg.can, leg.rest.can, BEAST_V[7].subVectors(F, C));
        this.aim(leg.pas, leg.rest.pas, BEAST_V[7].subVectors(T, F));
      } else {
        this.fk(leg.fem);
        const H = this.op[leg.fem];
        const J = BEAST_V[5].copy(leg.dirMet).applyAxisAngle(BEAST_AX, distal).negate().add(F);
        const K = this.solve2(H, J, leg.l1, leg.l2, -1, BEAST_V[6]);
        this.aim(leg.fem, leg.rest.fem, BEAST_V[7].subVectors(K, H));
        this.aim(leg.tib, leg.rest.tib, BEAST_V[7].subVectors(J, K));
        this.aim(leg.met, leg.rest.met, BEAST_V[7].subVectors(F, J));
        this.aim(leg.pas, leg.rest.pas, BEAST_V[7].subVectors(T, F));
      }
    }
    // ── Шия й голова ──
    const bodyPitch = pitch * alive + chestRot * alive;
    const nod = moving * (gw[0] * 0.035 * Math.sin(TAU * ph * 2) + gw[1] * 0.015 * Math.sin(TAU * ph * 2) + gw[2] * 0.1 * Math.sin(TAU * ph + 2));
    let neckT = s.neck + nod;
    let headT = s.headPitch;
    // Виття: шия догори, морда задерта.
    neckT = lerp(neckT, this.neckRest - 0.35, s.howl);
    headT = lerp(headT, -0.75, s.howl);
    // Прислухається (лисиця): голова опущена й нахилена вбік.
    neckT = lerp(neckT, this.neckRest + 0.45, s.listen);
    headT = lerp(headT, 0.85, s.listen);
    const dnMax = rig.neckMax - this.neckRest - bodyPitch;
    let dn = Math.min(neckT - this.neckRest - bodyPitch, dnMax);
    const yawN = s.yaw * alive;
    BEAST_E.set(dn * 0.55, yawN * 0.3, 0, 'YXZ');
    lq[I.neck1].setFromEuler(BEAST_E);
    BEAST_E.set(dn * 0.45, yawN * 0.35, 0, 'YXZ');
    lq[I.neck2].setFromEuler(BEAST_E);
    const roll = s.listen * 0.32 * Math.sin(this.time * 0.9) + s.listen * 0.12;
    let headRel = headT - this.restPitch - dn - bodyPitch;
    BEAST_E.set(headRel, yawN * 0.35, roll, 'YXZ');
    lq[I.head].setFromEuler(BEAST_E);
    this.fk(I.neck1);
    this.fk(I.neck2);
    this.fk(I.head);
    // Нюхати слід, рити, гризти, пастися: дотягнути ніс до землі.
    const reach = Math.max(s.ground, this.pounceLand) * alive;
    if (reach > 0.02) {
      const groundY = this.kind === 'boar' ? 0.03 : 0.025;
      for (let it = 0; it < 3; it++) {
        const nose = BEAST_V[8].copy(this.noseLocal).applyQuaternion(this.oq[I.head]).add(this.op[I.head]);
        const gap = nose.y - groundY * legLen / 0.5;
        if (Math.abs(gap) < 0.006) break;
        const extra = clamp(gap / Math.max(this.neckLen, 0.1), -0.3, 0.6) * reach;
        const dn2 = Math.min(dn + extra, dnMax);
        headRel -= (dn2 - dn) * 0.6 - Math.max(0, dn + extra - dnMax) * 0.8;
        headRel = Math.min(headRel, rig.headMax - this.restPitch - dn2 - bodyPitch);
        dn = dn2;
        BEAST_E.set(dn * 0.55, yawN * 0.3, 0, 'YXZ');
        lq[I.neck1].setFromEuler(BEAST_E);
        BEAST_E.set(dn * 0.45, yawN * 0.35, 0, 'YXZ');
        lq[I.neck2].setFromEuler(BEAST_E);
        BEAST_E.set(headRel, yawN * 0.35, roll, 'YXZ');
        lq[I.head].setFromEuler(BEAST_E);
        this.fk(I.neck1);
        this.fk(I.neck2);
        this.fk(I.head);
      }
      // Кабан рило штовхає землю ривками; вовк смикає здобич.
      if (this.kind === 'boar' && s.ground > 0.3) {
        const push = Math.max(0, Math.sin(this.chew * 5.2)) * 0.12 * s.ground;
        lq[I.head].multiply(BEAST_Q[4].setFromAxisAngle(BEAST_AX, -push));
      }
    }
    // ── Щелепа: виття, дихання після бігу, гризіння ──
    if (I.jaw !== undefined) {
      const pantK = s.pant * (0.4 + 0.25 * Math.sin(this.time * 14));
      const chewK = s.eat * Math.max(0, Math.sin(this.chew * 6.5));
      const jaw = (s.howl * (0.75 + 0.15 * Math.sin(this.time * 1.7)) + pantK * 0.45 + chewK * 0.6) * rig.jaw * alive;
      lq[I.jaw].setFromAxisAngle(BEAST_AX, jaw);
    }
    // ── Вуха ──
    const runW = gw[2] * moving;
    for (let i = 0; i < 2; i++) {
      const side = i === 0 ? -1 : 1;
      const ear = i === 0 ? I.earL : I.earR;
      const tw = i === this.twitchSide ? Math.sin(this.twitch * 20) * this.twitch * 0.35 : 0;
      const back = clamp(s.earsBack + runW * 0.5 + s.howl * 0.4 + crouch * 1.0, 0, 1);
      const k = rig.earK;
      let ex = (0.22 * s.alert - 0.75 * back * k + tw) * alive;
      let ez = side * (0.06 * s.alert - 0.05 * back - fall * 0.5);
      // Заєць: вуха вздовж спини в лежці й на бігу, сторч — коли насторожений.
      if (this.kind === 'hare') {
        ex = (0.1 * s.alert - 1.25 * back + tw * 0.5) * alive;
        ez = side * (0.1 * s.alert + 0.12 * (1 - back) * (1 - s.alert) - fall * 0.4);
      }
      // Лисиця прислухається: вуха вперед.
      ex += s.listen * 0.25;
      BEAST_E.set(ex, side * -0.15 * s.alert * alive, ez, 'XYZ');
      lq[ear].setFromEuler(BEAST_E);
    }
    // ── Хвіст ──
    const tk = rig.tail;
    const wag = Math.sin(this.flick * 23) * this.flick * 0.3 + moving * gw[1] * 0.08 * Math.sin(TAU * ph);
    let tailUp = s.tail * alive + Math.sin(this.flick * 18) * this.flick * 0.2;
    if (sit > 0.01) tailUp = lerp(tailUp, -0.15, sit);
    if (lie > 0.01) tailUp = lerp(tailUp, 0.3, lie);
    const tails = [I.tail1, I.tail2, I.tail3];
    for (let t = 0; t < 3; t++) {
      if (tails[t] === undefined) continue;
      BEAST_E.set(tailUp * tk[t] * 1.6, wag * (0.6 + t * 0.4), 0, 'XYZ');
      lq[tails[t]].setFromEuler(BEAST_E);
    }
    // ── Загибель: тіло на боці, ноги розслаблені ──
    if (fall > 0) {
      const lim = BEAST_Q[2];
      const relax = (name, x) => {
        const i = I[name];
        if (i === undefined) return;
        lim.setFromAxisAngle(BEAST_AX, x);
        lq[i].slerp(lim, fall);
      };
      for (const sd of ['L', 'R']) {
        const k = sd === 'L' ? 1 : 0.8;
        relax(`humF${sd}`, 0.55 * k);
        relax(`radF${sd}`, -0.3 * k);
        relax(`canF${sd}`, 0.3);
        relax(`pasF${sd}`, 0.3);
        relax(`femB${sd}`, -0.5 * k);
        relax(`tibB${sd}`, 0.5);
        relax(`metB${sd}`, -0.35);
        relax(`pasB${sd}`, 0.35);
        relax(`scapF${sd}`, 0.1);
      }
      relax('neck1', this.kind === 'boar' ? 0.2 : 0.55);
      relax('neck2', 0.3);
      relax('head', 0.1);
      relax('jaw', 0.12);
    }
    const bones = this.bones;
    for (let i = 0; i < bones.length; i++) bones[i].quaternion.copy(lq[i]);
    bones[I.root].position.copy(this.rootPos);
  }
}
